     1→import { type HTMLAttributes } from 'react';
     2→
     3→export type ProgressBarSize = 'xs' | 'sm' | 'md' | 'lg';
     4→export type ProgressBarVariant = 'default' | 'success' | 'warning' | 'error';
     5→
     6→export interface ProgressBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
     7→  value: number;
     8→  max?: number;
     9→  size?: ProgressBarSize;
    10→  variant?: ProgressBarVariant;
    11→  showLabel?: boolean;
    12→  labelFormatter?: (value: number, max: number) => string;
    13→  indeterminate?: boolean;
    14→  striped?: boolean;
    15→  animated?: boolean;
    16→}
    17→
    18→const sizeStyles: Record<ProgressBarSize, string> = {
    19→  xs: 'h-1',
    20→  sm: 'h-1.5',
    21→  md: 'h-2',
    22→  lg: 'h-3',
    23→};
    24→
    25→const variantStyles: Record<ProgressBarVariant, string> = {
    26→  default: 'bg-primary-500',
    27→  success: 'bg-accent-success',
    28→  warning: 'bg-accent-warning',
    29→  error: 'bg-accent-error',
    30→};
    31→
    32→export function ProgressBar({
    33→  value,
    34→  max = 100,
    35→  size = 'md',
    36→  variant = 'default',
    37→  showLabel = false,
    38→  labelFormatter = (v, m) => `${Math.round((v / m) * 100)}%`,
    39→  indeterminate = false,
    40→  striped = false,
    41→  animated = false,
    42→  className = '',
    43→  ...props
    44→}: ProgressBarProps) {
    45→  const percentage = Math.min(Math.max((value / max) * 100, 0), 100);
    46→
    47→  return (
    48→    <div className={className} {...props}>
    49→      {showLabel && (
    50→        <div className="flex justify-between items-center mb-1.5">
    51→          <span className="text-sm text-surface-300">Progress</span>
    52→          <span className="text-sm text-surface-400 font-mono">
    53→            {labelFormatter(value, max)}
    54→          </span>
    55→        </div>
    56→      )}
    57→
    58→      <div
    59→        role="progressbar"
    60→        aria-valuenow={indeterminate ? undefined : value}
    61→        aria-valuemin={0}
    62→        aria-valuemax={max}
    63→        className={`
    64→          w-full ${sizeStyles[size]}
    65→          bg-surface-700 rounded-full overflow-hidden
    66→        `}
    67→      >
    68→        <div
    69→          className={`
    70→            h-full rounded-full
    71→            ${variantStyles[variant]}
    72→            ${indeterminate ? 'animate-indeterminate' : 'transition-all duration-300 ease-out'}
    73→            ${striped ? 'progress-striped' : ''}
