        label="Quality"
        value={options.quality}
        min={1}
        max={100}
        onChange={(e) => onChange({ quality: Number(e.target.value) })}
        valueFormatter={(v) => `${v}%`}
        disabled={disabled}
      />

      {/* Color Count */}
      <div>
        <Slider
          label="Colors"
          value={options.colorCount}
          min={2}
          max={256}
          step={2}
