  className?: string;
}

const stageIcons: Record<EncodingState, IconName> = {
  queued: 'clock',
  preparing: 'cog',
  encoding: 'film',
  optimizing: 'adjustments-horizontal',
  completed: 'check-circle',
  failed: 'x-circle',
  cancelled: 'x-mark',
};

export function EncodingStage({
  stage,
  label,
