        return (
          <div
            key={preset.id}
            className={`
              group p-3 rounded-lg border cursor-pointer
              transition-all duration-150
              ${isSelected
                ? 'border-primary-500 bg-primary-500/10'
                : 'border-surface-700 bg-surface-800 hover:border-surface-600'
