                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      onEdit(preset);
                    }}
                    disabled={disabled}
                  >
                    <Icon name="pencil-square" size="sm" />
                  </Button>
                )}

                {!isDefault && onSetDefault && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      onSetDefault(preset);
                    }}
                    disabled={disabled}
                    title="Set as default"
                  >
                    <Icon name="check-circle" size="sm" />
                  </Button>
                )}

                {!preset.isBuiltIn && onDelete && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDelete(preset);
                    }}
                    disabled={disabled}
                  >
                    <Icon name="trash" size="sm" className="text-accent-error" />
                  </Button>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

